import ShoppingItem from "./ShoppingItem";

function ShoppingItemList({ items }) {
  if (!items || items.length === 0) {
    return <p>Your shopping list is empty</p>;
  }
  return (
    <ul id="item-list" className="items">
      {items.map((item) => (
        <li>{item.text}</li>
      ))}
    </ul>
  );
}

export default ShoppingItemList;
